    "tx_power_dbm": 7,
    "obss_pd_dbm": -72
  },
  "ap2": {
    "tx_power_dbm": 7,
    "obss_pd_dbm": -72
  },
  "ap3": {
    "tx_power_dbm": 7,
    "obss_pd_dbm": -72
  },
  "_sr": {
    "concurrent_group": ["ap1", "ap3"],
    "non_concurrent_aps": ["ap2"]
  }
}
```

